begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) values
('f1111111-1111-4111-8111-111111111111','clinical-owner@example.invalid',now(),'{}','{}'),
('f2222222-2222-4222-8222-222222222222','clinical-other@example.invalid',now(),'{}','{}'),
('f3333333-3333-4333-8333-333333333333','clinical-staff@example.invalid',now(),'{}','{}');
insert into public.tenants(id,name) values('faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Clinical A'),('fbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Clinical B');
insert into public.users(id,tenant_id,display_name,role,clinical_access) values
('f1111111-1111-4111-8111-111111111111','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Owner','owner',true),
('f2222222-2222-4222-8222-222222222222','fbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Other','owner',true),
('f3333333-3333-4333-8333-333333333333','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Staff','operator',true);
insert into public.clients(id,tenant_id,first_name,last_name) values('faaaaaaa-1111-4111-8111-111111111111','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Synthetic','Client');
insert into public.locations(id,tenant_id,name) values('faaaaaaa-2222-4222-8222-222222222222','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Location');
insert into public.services(id,tenant_id,name,duration_minutes) values('faaaaaaa-3333-4333-8333-333333333333','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Service',60);
insert into public.appointments(id,tenant_id,client_id,service_id,location_id,operator_id,service_name,price_cents,starts_at,ends_at)
values('faaaaaaa-4444-4444-8444-444444444444','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','faaaaaaa-1111-4111-8111-111111111111','faaaaaaa-3333-4333-8333-333333333333','faaaaaaa-2222-4222-8222-222222222222','f1111111-1111-4111-8111-111111111111','Service',5000,now()+interval '2 days',now()+interval '2 days 1 hour');
create temporary table results(label text primary key,id uuid);
grant all on results to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into results values('consent',(public.publish_clinical_template('f0000000-1111-4111-8111-111111111111',null,0,'consent','Consenso di prova','Testo sintetico non destinato a uso reale.','[]',null)).id);
insert into results values('anamnesis',(public.publish_clinical_template('f0000000-2222-4222-8222-222222222222',null,0,'anamnesis','Anamnesi di prova','Questionario sintetico non clinico.','[{"id":"f9999999-1111-4111-8111-111111111111","label":"Domanda sintetica","type":"yes_no","required":true}]',null)).id);
insert into results values('pigment',(public.save_pigment('f0000000-3333-4333-8333-333333333333',null,0,'Brand A','Pigment A','CODE',true)).id);
reset role;
-- Trusted fixture: policy tests do not pretend this is a real Storage upload.
insert into public.stored_files(id,tenant_id,pigment_id,kind,created_by,request_id,state,upload_path,object_path,expected_size,expected_sha256,mime_type,size_bytes,sha256,width,height,ready_at)
values('faaaaaaa-5555-4555-8555-555555555555','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select id from results where label='pigment'),'pigment_label','f1111111-1111-4111-8111-111111111111',gen_random_uuid(),'ready','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/faaaaaaa-5555-4555-8555-555555555555/upload','faaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/faaaaaaa-5555-4555-8555-555555555555/image',100,repeat('a',64),'image/jpeg',100,repeat('b',64),10,10,now());
set local role authenticated;
insert into results values('lot',(public.save_pigment_lot('f0000000-4444-4444-8444-444444444444',null,0,(select id from results where label='pigment'),'LOT-1',current_date+365,'faaaaaaa-5555-4555-8555-555555555555','Synthetic label',true)).id);
insert into results values('preparation',(public.save_treatment_preparation('f0000000-5555-4555-8555-555555555555','faaaaaaa-4444-4444-8444-444444444444',1,0,(select id from results where label='consent'),(select id from results where label='anamnesis'),'{"f9999999-1111-4111-8111-111111111111":true}',array[(select id from results where label='lot')])).id);
create temporary table capabilities(label text primary key,data jsonb);
reset role;
grant all on capabilities,results to authenticated,service_role;
set local role authenticated;
insert into capabilities values('first',public.create_signature_request('f0000000-8888-4888-8888-888888888888','faaaaaaa-4444-4444-8444-444444444444',1,1,'link'));
select ok((select data->>'token' ~ '^[a-f0-9]{64}$' from capabilities where label='first'),'signature token has 256 random bits');
select is(public.create_signature_request('f0000000-8888-4888-8888-888888888888','faaaaaaa-4444-4444-8444-444444444444',1,1,'link')->>'token',null,'creation retry cannot retrieve plaintext token');
select throws_ok($$select public.create_signature_request('f0000000-8888-4888-8888-888888888888','faaaaaaa-4444-4444-8444-444444444444',1,1,'tablet')$$,'23505',null,'issuance binds mode and revisions');
select throws_ok($$select public.create_signature_request(gen_random_uuid(),'faaaaaaa-4444-4444-8444-444444444444',null,1,'link')$$,'40001',null,'null revision is not accepted');
select throws_ok($$select * from app_private.signature_payloads$$,'42501',null,'owner cannot directly read signature snapshots or hashes');
select throws_ok($$select * from app_private.signed_payloads$$,'42501',null,'owner cannot directly read handwriting');
select throws_ok($$select public.claim_document_job(gen_random_uuid())$$,'42501',null,'normal session cannot run privileged PDF worker');
reset role;
select is((select count(*)::int from app_private.signature_payloads sp join capabilities x on sp.request_id=(x.data->'link'->>'id')::uuid where sp.token_hash=encode(extensions.digest(x.data->>'token','sha256'),'hex')),1,'only token digest is persisted');
create function pg_temp.signature(label text,action text,input jsonb default null) returns jsonb language sql as $$
 select public.use_signature_request(encode(extensions.digest((select data->>'token' from capabilities where capabilities.label=$1),'sha256'),'hex'),$2,$3);
$$;
set local role anon;
select throws_ok($$select * from public.consents$$,'42501',null,'anonymous metadata denied');
select throws_ok($$select public.use_signature_request(repeat('a',64),'read')$$,'42501',null,'anonymous RPC cannot bypass gateway');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{}',true);
insert into capabilities values('read',pg_temp.signature('first','read'));
select is((select data->>'ok' from capabilities where label='read'),'true','capability reads its frozen document');
select is((select data->'context'->'snapshot'->>'client_name' from capabilities where label='read'),'Synthetic Client','review contains intended signer context');
select is((select data->'context'->'snapshot'->'answers'->>'f9999999-1111-4111-8111-111111111111' from capabilities where label='read'),'true','signature review includes pinned answers');
select is((select data->'context'->'snapshot'->'lots'->0->>'lot_number' from capabilities where label='read'),'LOT-1','signature review includes historical lot');
select ok((select not(data->'context'->'snapshot' ? 'client_id') and not(data->'context'->'snapshot' ? 'email') from capabilities where label='read'),'review excludes contact details and generic identifiers');
select is(pg_temp.signature('first','label','{"id":"faaaaaaa-5555-4555-8555-555555555555"}')->>'ok','true','only attached historical label is available');
select is(pg_temp.signature('first','label',jsonb_build_object('id',gen_random_uuid()))->>'status','410','unrelated label cannot be read');
reset role;
select is((select count(*)::int from public.audit_log where action='signature.read' and resource_id=(select (data->'link'->>'id')::uuid from capabilities where label='first')),1,'document review is audited');
insert into capabilities values('input',jsonb_build_object('request_id','f0000000-9999-4999-8999-999999999999','snapshot_hash',(select data->'context'->>'snapshot_hash' from capabilities where label='read'),'signer_name','Synthetic Signer','confirmed',true,'signature','[[[0.1,0.2],[0.2,0.3],[0.3,0.4],[0.4,0.3],[0.5,0.2],[0.6,0.4]]]'::jsonb));
set local role service_role;
select is(pg_temp.signature('first','sign',(select data-'confirmed' from capabilities where label='input'))->>'status','422','explicit consent cannot be omitted');
select is(pg_temp.signature('first','sign',(select jsonb_set(data,'{snapshot_hash}',to_jsonb(repeat('a',64))) from capabilities where label='input'))->>'status','422','signature must acknowledge exactly the reviewed snapshot hash');
select is(pg_temp.signature('first','sign',(select jsonb_set(data,'{signature}','[[[0.1,0.2],[0.1,0.2]]]') from capabilities where label='input'))->>'status','422','empty or point-only signatures rejected');
select is(pg_temp.signature('first','sign',(select jsonb_set(data,'{signature}','[[[0.1,0.2],[9,0.2]]]') from capabilities where label='input'))->>'status','422','signature coordinates bounded');
reset role;
create function pg_temp.fail_signature_audit() returns trigger language plpgsql as $$ begin if new.action in('signature.read','consent.signed') then raise exception 'AUDIT_UNAVAILABLE' using errcode='XX000'; end if;return new;end;$$;
create trigger fail_signature_audit before insert on public.audit_log for each row execute function pg_temp.fail_signature_audit();
set local role service_role;
select throws_ok($$select pg_temp.signature('first','read')$$,'XX000','AUDIT_UNAVAILABLE','failed audit prevents releasing clinical snapshot');
select throws_ok($$select pg_temp.signature('first','sign',(select data from capabilities where label='input'))$$,'XX000','AUDIT_UNAVAILABLE','signature audit failure rolls back the whole transaction');
reset role;
drop trigger fail_signature_audit on public.audit_log;
select is((select count(*)::int from public.consents),0,'failed audit leaves no consent');
select is((select count(*)::int from app_private.document_jobs),0,'failed audit leaves no orphan job');
select is((select used_at from public.consent_requests where id=(select (data->'link'->>'id')::uuid from capabilities where label='first')),null,'failed audit leaves token usable');
update public.pigment_lots set active=false where id=(select id from results where label='lot');
set local role service_role;
select is(pg_temp.signature('first','sign',(select data from capabilities where label='input'))->>'status','410','a lot archived after issuance blocks new signing');
reset role;
update public.pigment_lots set active=true where id=(select id from results where label='lot');
set local role service_role;
insert into capabilities values('signed',pg_temp.signature('first','sign',(select data from capabilities where label='input')));
select is((select data->>'ok' from capabilities where label='signed'),'true','signature and snapshot accepted atomically');
select is(pg_temp.signature('first','sign',(select data from capabilities where label='input'))->'receipt',(select data->'receipt' from capabilities where label='signed'),'identical retry returns the original receipt');
select is(pg_temp.signature('first','sign',(select jsonb_set(data,'{signer_name}','"Another name"') from capabilities where label='input'))->>'status','410','changed replay cannot replace signed document');
select is(pg_temp.signature('first','read')->>'status','410','consumed capability never reopens clinical content');
reset role;
insert into results values('document',(select (data->'receipt'->>'id')::uuid from capabilities where label='signed'));
select is((select count(*)::int from app_private.document_jobs),1,'one recoverable PDF job exists');
select is((select content_hash from public.consents where id=(select id from results where label='document')),(select encode(extensions.digest(payload::text,'sha256'),'hex') from app_private.signed_payloads where consent_id=(select id from results where label='document')),'signed hash covers timestamp, statement, handwriting and frozen contents');
select throws_ok($$update app_private.signed_payloads set payload='{}'$$,'23514','IMMUTABLE_DOCUMENT','signed payload cannot be edited');
select throws_ok($$delete from app_private.signed_payloads$$,'23514','IMMUTABLE_DOCUMENT','signed payload cannot be deleted');
select throws_ok($$update public.consents set content_hash=repeat('c',64)$$,'23514','IMMUTABLE_DOCUMENT','signed metadata cannot be rewritten');
select throws_ok($$update app_private.signature_payloads set snapshot='{}'$$,'23514','IMMUTABLE_DOCUMENT','reviewed snapshot cannot be rewritten');
update app_private.preparation_answers set answers='{}' where preparation_id=(select id from results where label='preparation');
select is((select payload->'snapshot'->'answers'->>'f9999999-1111-4111-8111-111111111111' from app_private.signed_payloads),'true','later draft edits preserve signed answers');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.consents),0,'other tenant cannot list signed documents');
select throws_ok($$select public.read_consent_file((select id from results where label='document'))$$,'P0002',null,'other tenant cannot obtain PDF path');
select throws_ok($$select public.request_document_retry((select id from results where label='document'))$$,'P0002',null,'other tenant cannot trigger document processing');
select set_config('request.jwt.claims','{"sub":"f3333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select is((select count(*)::int from public.consents),0,'unassigned clinical operator cannot list documents');
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$select public.create_signature_request(gen_random_uuid(),'faaaaaaa-4444-4444-8444-444444444444',1,1,'link')$$,'22023','ALREADY_SIGNED','one revision cannot be signed twice');
select throws_ok($$select public.read_consent_file((select id from results where label='document'))$$,'22023','DOCUMENT_PENDING','PDF is never presented ready before verification');
reset role;
set local role service_role;
insert into capabilities values('claim1',public.claim_document_job((select id from results where label='document')));
select ok((select data->>'claim' is not null from capabilities where label='claim1'),'worker leases job');
select is(public.claim_document_job((select id from results where label='document')),null,'second worker cannot claim active lease');
select throws_ok($$select public.complete_document_job((select id from results where label='document'),gen_random_uuid(),repeat('b',64),100)$$,'40001','STALE_CLAIM','incorrect fencing token cannot finalize');
select throws_ok($$select public.complete_document_job((select id from results where label='document'),(select (data->>'claim')::uuid from capabilities where label='claim1'),repeat('b',64),100)$$,'23514','INVALID_DOCUMENT','missing Storage object cannot finalize');
select public.fail_document_job((select id from results where label='document'),(select (data->>'claim')::uuid from capabilities where label='claim1'),'render_failed');
reset role;
select is((select document_state from public.consents),'failed','render failure visible without losing signature');
select is((select count(*)::int from app_private.signed_payloads),1,'render failure preserves original signature');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select lives_ok($$select public.request_document_retry((select id from results where label='document'))$$,'owner can recover without signing again');
reset role;
set local role service_role;
insert into capabilities values('claim2',public.claim_document_job((select id from results where label='document')));
reset role;
select isnt((select data->>'claim' from capabilities where label='claim1'),(select data->>'claim' from capabilities where label='claim2'),'retry has a new fencing token');
select is((select data->>'path' from capabilities where label='claim1'),(select data->>'path' from capabilities where label='claim2'),'retry reuses deterministic immutable artifact path');
update app_private.document_jobs set lease_until=now()-interval '1 minute' where consent_id=(select id from results where label='document');
update app_private.document_jobs set attempts=5;
set local role service_role;
select is(public.claim_next_document_job(),null,'automatic recovery respects retry budget');
reset role;
update app_private.document_jobs set attempts=4,failure_code='integrity_failed';
set local role service_role;
select is(public.claim_next_document_job(),null,'integrity failure requires intervention');
reset role;
update app_private.document_jobs set attempts=2,failure_code='render_failed',next_attempt_at=clock_timestamp()+interval '1 hour';
set local role service_role;
select is(public.claim_next_document_job(),null,'automatic recovery respects backoff');
reset role;
update app_private.document_jobs set next_attempt_at=clock_timestamp()-interval '1 second';
set local role service_role;
insert into capabilities values('claim3',public.claim_next_document_job());
select ok((select data->>'claim' is not null from capabilities where label='claim3'),'automatic worker recovers expired PDF lease');
select is(public.claim_next_document_job(),null,'automatic worker cannot duplicate active PDF lease');
select throws_ok($$select public.complete_document_job((select id from results where label='document'),(select (data->>'claim')::uuid from capabilities where label='claim2'),repeat('b',64),100)$$,'40001','STALE_CLAIM','expired worker cannot finalize after replacement');
reset role;
-- SQL fixture validates the boundary; browser tests perform real upload and hashing.
insert into storage.objects(bucket_id,name,metadata) values('glow-documents',(select data->>'path' from capabilities where label='claim3'),'{"size":100,"mimetype":"application/pdf"}');
set local role service_role;
select lives_ok($$select public.complete_document_job((select id from results where label='document'),(select (data->>'claim')::uuid from capabilities where label='claim3'),repeat('b',64),100)$$,'only a verified persisted artifact is marked ready');
select is(public.claim_document_job((select id from results where label='document')),null,'ready PDF cannot be rerendered or overwritten');
select is(public.claim_next_document_job(),null,'automatic worker cannot rerender ready artifact');
reset role;
select is((select document_state from public.consents),'ready','PDF is ready after finalization');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select is(public.read_consent_file((select id from results where label='document'))->>'sha256',repeat('b',64),'authorized audited read returns expected checksum');
select is((select count(*)::int from storage.objects where bucket_id='glow-documents'),0,'normal Storage API cannot list signed PDFs');
reset role;
select is((select count(*)::int from public.audit_log where action='document.read'),1,'PDF reads leave an audit record');
select ok((select not public from storage.buckets where id='glow-documents'),'document bucket is private');
select is((select count(*)::int from public.audit_log where action='consent.signed' and actor_id is not null),0,'client signing does not impersonate professional');
insert into app_private.signature_rate_limits values('old',date_trunc('minute',clock_timestamp())-interval '2 hours',1);
set local role service_role;
select is((select jsonb_agg(public.use_signature_request(repeat('e',64),'read') order by s)->30->>'status' from generate_series(1,31) s),'429','persistent token limiter counts rejected attempts');
reset role;
select is((select max(attempts) from app_private.signature_rate_limits where key=repeat('e',64)),31,'rejected requests commit their counter');
select is((select count(*)::int from app_private.signature_rate_limits where key='old'),0,'expired rate windows are cleaned');
select * from finish();
rollback;
